$news_sources=array(
 array('label'=>'Kinh doanh','feed'=>'https://vnexpress.net/rss/kinh-doanh.rss','home'=>'https://vnexpress.net/kinh-doanh'),
 array('label'=>'Khoa học & công nghệ','feed'=>'https://vnexpress.net/rss/khoa-hoc-cong-nghe.rss','home'=>'https://vnexpress.net/khoa-hoc-cong-nghe')
