foreach($news_sources as $source):
 $key='dttl_headlines_'.md5($source['feed']);$items=get_transient($key);$stale=false;
 if(false===$items){
  $items=array();$feed=fetch_feed($source['feed']);
  if(!is_wp_error($feed)) foreach($feed->get_items(0,4) as $item){
   $url=$item->get_permalink();$host=strtolower((string)wp_parse_url($url,PHP_URL_HOST));
   if($host!=='vnexpress.net' && $host!=='www.vnexpress.net') continue;
   $items[]=array('title'=>wp_strip_all_tags(html_entity_decode($item->get_title(),ENT_QUOTES,'UTF-8')),'url'=>$url,'date'=>$item->get_date('U'));
  }
  if($items){set_transient($key,$items,HOUR_IN_SECONDS);update_option($key.'_last',$items,false);}
  else {$items=get_option($key.'_last',array());$stale=true;set_transient($key.'_error',1,10*MINUTE_IN_SECONDS);}
 }
?>
