</ul><?php else: ?><p>Chưa tải được tiêu đề từ nguồn.</p><?php endif; ?>
<a class="simple-link" href="<?php echo esc_url($source['home']); ?>" target="_blank" rel="noopener noreferrer">Xem tại VnExpress ↗</a></div>
<?php endforeach; ?>
